settings.custom-liquid:
{% if collection.metafields.custom.short_banner_image != blank %}
  <div class="short-banner-wrapper">
    <img
      src="{{ collection.metafields.custom.short_banner_image | image_url: width: 1762 }}"
      alt="Short Banner"
      class="short-banner-img"
      loading="lazy"
      width="1762"
      height="275"
    >
  </div>
{% endif %}
<style>
  .short-banner-wrapper {
    margin: 0;
    padding: 0;
    margin-bottom: 15px;
  }
  .short-banner-img {
    width: 100%;
    height: auto;
    object-fit: cover;
    display: block;
  }
  @media screen and (max-width: 768px) {
    .short-banner-img {
      max-height: 180px;
    }
  }
  @media screen and (max-width: 480px) {
    .short-banner-img {
      max-height: 140px;
    }
  }
</style>
